import codecs
events = []
class Text(str):
    def __buffer__(self, flags):
        events.append('buffer')
        return memoryview(b'wrong')
    def __str__(self):
        raise AssertionError('string conversion')
def search(name):
    events.append('search')
codecs.register(search)
for source in ('', 'text', Text(''), Text('text')):
    for build in (lambda: str(source, 'codec-reject'), lambda: str.__new__(str, source, 'codec-reject')):
        try:
            build()
        except TypeError as error:
            assert error.args == ('decoding str is not supported',)
            print(type(error).__name__, error.args)
        else:
            raise AssertionError('text accepted')
assert events == []

